// Recibe output del AI Agent (campo .output) o del HTTP Ollama (campo .response)
const raw = ($input.item.json.output || $input.item.json.response || '{}')
  .replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

let res = {};
try {
  const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
  res = JSON.parse(s !== -1 && e > s ? raw.substring(s, e+1) : raw);
} catch(e) { res = {}; }

const keywords    = Array.isArray(res.keywords) ? res.keywords : [res.keywords || 'PC sobremesa'].filter(Boolean);
const presupuesto = Number(res.presupuesto) || 1000;
// pMin = 65% del presupuesto → filtra productos demasiado baratos
const pMin        = Number(res.pMin) || Math.round(presupuesto * 0.65);
const tipo        = res.tipo || 'Sobremesa';
const must        = Array.isArray(res.must)   ? res.must   : [];
const nice        = Array.isArray(res.nice)   ? res.nice   : [];
const marcas      = Array.isArray(res.marcas) ? res.marcas : [];
const pantalla    = res.pantalla || null;

// Construir query optimizada para Google Shopping:
// Incluye tipo + marcas + must specs para encontrar productos específicos
const partes = [tipo];
if (marcas.length > 0) partes.push(marcas.slice(0,2).join(' '));
if (must.length > 0) partes.push(must.slice(0,2).join(' '));
if (keywords.length > 0 && !partes.some(p => keywords[0] && p.toLowerCase().includes(keywords[0].toLowerCase()))) {
  partes.push(keywords.slice(0,2).join(' '));
}
const q = partes.filter(Boolean).join(' ').trim();

return [{ json: { q, keywords, pMax: presupuesto, pMin, tipo, must, nice, marcas, pantalla, retryCount: 0 } }];

