  return budgetProximity(b.price) - budgetProximity(a.price); // si no, el más cercano al presupuesto máximo
};

inBudget.sort(sortFn);
outBudget.sort(sortFn);

const sorted = [...inBudget, ...outBudget].slice(0, 10);

